namespace AiQuery.Infrastructure.Persistence.Records;

internal sealed class QueryRequestRecord { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid OrganizationId { get; set; } public Guid SoftwareProductId { get; set; } public Guid SoftwareVersionId { get; set; } public Guid? SnapshotId { get; set; } public Guid ActorId { get; set; } public required string Question { get; set; } public required string State { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } public long Version { get; set; } public SoftwareProductRecord? SoftwareProduct { get; set; } public SoftwareVersionRecord? SoftwareVersion { get; set; } }
internal sealed class QueryAttemptRecord { public Guid Id { get; set; } public Guid QueryRequestId { get; set; } public int AttemptNumber { get; set; } public required string State { get; set; } public string? ProviderCode { get; set; } public DateTimeOffset StartedAtUtc { get; set; } public DateTimeOffset? CompletedAtUtc { get; set; } public string? FailureCode { get; set; } }
internal sealed class QueryResultRecord { public Guid Id { get; set; } public Guid QueryAttemptId { get; set; } public required string SqlText { get; set; } public required string ParametersJson { get; set; } public required string DisplaySpecJson { get; set; } public required string SnapshotHash { get; set; } public required string PolicyHash { get; set; } public DateTimeOffset ExpiresAtUtc { get; set; } public string? Signature { get; set; } }
