internal sealed class FeedbackEntryRecord { public Guid Id { get; set; } public Guid QueryResultId { get; set; } public Guid ActorId { get; set; } public required string ActorType { get; set; } public bool Helpful { get; set; } public string? Comment { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } }

internal sealed class AuditEventRecord { public Guid Id { get; set; } public Guid? TenantId { get; set; } public required string EventCode { get; set; } public required string CorrelationId { get; set; } public string? ActorId { get; set; } public DateTimeOffset OccurredAtUtc { get; set; } public required string SafeMetadataJson { get; set; } }
