internal sealed class OutboxMessageRecord { public Guid Id { get; set; } public DateTimeOffset OccurredAtUtc { get; set; } public required string Type { get; set; } public required string PayloadJson { get; set; } public DateTimeOffset? ProcessedAtUtc { get; set; } public int AttemptCount { get; set; } public DateTimeOffset? NextAttemptAtUtc { get; set; } }
